"""Brute-force the AVD-total chromatic number of C(G) for small graphs and
confirm it equals the theoretical lower bound |V| + 1."""
from __future__ import annotations
from itertools import combinations
from typing import Dict, FrozenSet, List, Optional, Set, Tuple

Node = Tuple[str, object]


def total_graph_of_central(n: int, edges: List[Tuple[int, int]]):
    V = list(range(n))
    E = [frozenset(e) for e in edges]
    cg_nodes = [("V", v) for v in V] + [("S", e) for e in E]
    cg_edges: List[FrozenSet[Node]] = []
    for u, w in combinations(V, 2):
        if frozenset((u, w)) not in E:
            cg_edges.append(frozenset({("V", u), ("V", w)}))
    for e in E:
        for u in e:
            cg_edges.append(frozenset({("V", u), ("S", e)}))
    total_nodes = list(cg_nodes) + [("E", e) for e in cg_edges]
    adj: Dict[Node, Set[Node]] = {x: set() for x in total_nodes}
    for e in cg_edges:
        a, b = tuple(e)
        adj[a].add(b); adj[b].add(a)
        en = ("E", e)
        for endpoint in e:
            adj[endpoint].add(en); adj[en].add(endpoint)
    for e1, e2 in combinations(cg_edges, 2):
        if e1 & e2:
            adj[("E", e1)].add(("E", e2)); adj[("E", e2)].add(("E", e1))
    return total_nodes, adj, cg_edges, cg_nodes


def find_avd(n: int, edges: List[Tuple[int, int]], k: int) -> bool:
    total_nodes, adj, cg_edges, cg_nodes = total_graph_of_central(n, edges)
    order = sorted(total_nodes, key=lambda x: len(adj[x]), reverse=True)
    coloring: Dict[Node, int] = {}

    def cset(v: Node) -> FrozenSet[int]:
        cols = {coloring[v]}
        for e in cg_edges:
            if v in e:
                cols.add(coloring[("E", e)])
        return frozenset(cols)

    def avd_ok() -> bool:
        for a, b in combinations(cg_nodes, 2):
            if b in adj[a] and cset(a) == cset(b):
                return False
        return True

    def bt(i: int) -> bool:
        if i == len(order):
            return avd_ok()
        node = order[i]
        used = {coloring[nb] for nb in adj[node] if nb in coloring}
        limit = 1 if i == 0 else k
        for c in range(limit):
            if c in used:
                continue
            coloring[node] = c
            if bt(i + 1):
                return True
            del coloring[node]
        return False

    return bt(0)


def chromatic(n: int, edges: List[Tuple[int, int]]) -> int:
    k = 1
    while not find_avd(n, edges, k):
        k += 1
    return k


def demo() -> None:
    for name, n, edges in [
        ("P_3", 3, [(0, 1), (1, 2)]),
        ("P_4", 4, [(0, 1), (1, 2), (2, 3)]),
    ]:
        val = chromatic(n, edges)
        print(f"{name}: AVD-total chromatic number of C({name}) = {val}, "
              f"lower bound |V|+1 = {n + 1}, match = {val == n + 1}")


if __name__ == "__main__":
    demo()

