from __future__ import annotations
from itertools import combinations
from typing import List, Optional, Tuple


def lower_bound_certificate(
    n: int, edges: List[Tuple[int, int]]
) -> Optional[Tuple[int, int, int]]:
    """Return a local certificate (u, w, bound) that chi''_a(C(G)) >= |V| + 1,
    or None if G is complete (bound vacuous).

    The certificate is a pair of distinct non-adjacent vertices u, w of G. In
    C(G) they are adjacent and share the degree |V| - 1, so the equal-degree
    obstruction forbids a palette of size |V|. Complexity: O(|V|^2)."""
    E = {frozenset(e) for e in edges}
    for u, w in combinations(range(n), 2):
        if frozenset((u, w)) not in E:
            return (u, w, n + 1)
    return None

from __future__ import annotations
from itertools import combinations
from typing import Dict, FrozenSet, List, Optional, Set, Tuple

Node = Tuple[str, object]


def avd_total_chromatic_number(
    n: int, edges: List[Tuple[int, int]], k_max: int = 12
) -> int:
    """Compute the AVD-total chromatic number of the central graph C(G) by
    backtracking search over proper total colourings, checking the AVD
    condition on completion. Returns the least admissible palette size.

    Worst-case exponential; effective for small graphs thanks to
    degree-descending variable ordering and symmetry breaking on the first
    node."""
    V = list(range(n))
    E = [frozenset(e) for e in edges]
    cg_nodes: List[Node] = [("V", v) for v in V] + [("S", e) for e in E]
    cg_edges: List[FrozenSet[Node]] = []
    for u, w in combinations(V, 2):
        if frozenset((u, w)) not in E:
            cg_edges.append(frozenset({("V", u), ("V", w)}))
    for e in E:
        for u in e:
            cg_edges.append(frozenset({("V", u), ("S", e)}))
    total_nodes: List[Node] = list(cg_nodes) + [("E", e) for e in cg_edges]
    adj: Dict[Node, Set[Node]] = {x: set() for x in total_nodes}
    for e in cg_edges:
        a, b = tuple(e)
        adj[a].add(b); adj[b].add(a)
        en: Node = ("E", e)
        for endpoint in e:
            adj[endpoint].add(en); adj[en].add(endpoint)
    for e1, e2 in combinations(cg_edges, 2):
        if e1 & e2:
            adj[("E", e1)].add(("E", e2)); adj[("E", e2)].add(("E", e1))

    order = sorted(total_nodes, key=lambda x: len(adj[x]), reverse=True)

    def try_k(k: int) -> bool:
        coloring: Dict[Node, int] = {}

        def cset(v: Node) -> FrozenSet[int]:
            cols = {coloring[v]}
            for e in cg_edges:
                if v in e:
                    cols.add(coloring[("E", e)])
            return frozenset(cols)

        def avd_ok() -> bool:
            for a, b in combinations(cg_nodes, 2):
                if b in adj[a] and cset(a) == cset(b):
                    return False
            return True

        def bt(i: int) -> bool:
            if i == len(order):
                return avd_ok()
            node = order[i]
            used = {coloring[nb] for nb in adj[node] if nb in coloring}
            limit = 1 if i == 0 else k
            for c in range(limit):
                if c in used:
                    continue
                coloring[node] = c
                if bt(i + 1):
                    return True
                del coloring[node]
            return False

        return bt(0)

    for k in range(1, k_max + 1):
        if try_k(k):
            return k
    raise RuntimeError("no AVD total colouring within k_max colours")
